# chevron::common::units::DigitalSize

*Declaration Draft*

---

```cpp
#pragma once

#include <cstddef>
#include <cstdint>
#include <compare>
#include <ratio>
#include <stdexcept>
#include <type_traits>

namespace chevron::common::units {

    /**
     * @brief Strongly-typed digital size quantity with unit encoded in the type.
     *
     * @tparam Ratio A std::ratio specialization declaring how many bytes one
     *               unit of this type represents (e.g. std::ratio<1048576, 1>
     *               for mebibytes).
     *
     * DigitalSize is a value type that represents a quantity of digital storage
     * in a specific unit. The unit is carried in the type via the Ratio template
     * parameter, allowing function signatures to demand a specific unit. All
     * instances use std::uint64_t as their underlying storage regardless of unit.
     *
     * Arithmetic between different units promotes to a common representation
     * following std::chrono::duration rules. Lossless conversions (coarser to
     * finer units) are implicit; lossy conversions (finer to coarser) are
     * explicit.
     *
     * Conforms to the IEC binary convention: 1 KiB = 1024 bytes, 1 MiB = 1024 KiB,
     * and so on.
     */
    template <typename Ratio>
    class DigitalSize {
    public:
        using ratio_type = Ratio;
        using rep_type = std::uint64_t;

        // ---- Construction ----

        /**
         * @brief Default-constructs a DigitalSize representing zero units.
         */
        constexpr DigitalSize() noexcept = default;

        /**
         * @brief Constructs a DigitalSize from a raw count in this type's unit.
         *
         * @param count The number of units (not bytes) this instance represents.
         */
        constexpr explicit DigitalSize(rep_type count) noexcept;

        /**
         * @brief Implicit conversion from a finer-unit DigitalSize.
         *
         * Enabled only when the source ratio is a whole-number multiple of this
         * type's ratio — that is, when the conversion cannot lose information.
         * Lossy conversions must go through explicit_cast_from().
         */
        template <typename OtherRatio>
        constexpr DigitalSize(const DigitalSize<OtherRatio>& other) noexcept
            requires (/* OtherRatio is losslessly convertible to Ratio */);

        constexpr DigitalSize(const DigitalSize&) noexcept = default;
        constexpr DigitalSize(DigitalSize&&) noexcept = default;
        constexpr DigitalSize& operator=(const DigitalSize&) noexcept = default;
        constexpr DigitalSize& operator=(DigitalSize&&) noexcept = default;

        ~DigitalSize() = default;

        // ---- Accessors ----

        /**
         * @brief Returns the raw count in this type's unit.
         *
         * For a MiB instance holding 64 mebibytes, this returns 64.
         * Use bytes() to retrieve the canonical byte count.
         */
        constexpr rep_type count() const noexcept;

        /**
         * @brief Returns the canonical byte count as a 64-bit unsigned integer.
         *
         * Regardless of this instance's unit, bytes() returns the total byte
         * count it represents. For a MiB instance holding 64 mebibytes, this
         * returns 67,108,864.
         */
        constexpr rep_type bytes() const noexcept;

        /**
         * @brief Returns the byte count as std::size_t with runtime range checking.
         *
         * On 64-bit platforms this is a trivial conversion that the compiler
         * elides. On 32-bit platforms this performs a range check and throws
         * std::overflow_error if the value does not fit in std::size_t.
         *
         * @throws std::overflow_error if the byte count exceeds SIZE_MAX.
         */
        std::size_t to_size_t() const;

        // ---- Explicit conversion ----

        /**
         * @brief Explicitly converts from any other DigitalSize, truncating if needed.
         *
         * This is the escape hatch for lossy conversions (e.g. converting a
         * byte count to MiB where the byte count is not a multiple of 1 MiB).
         * Truncation is toward zero.
         */
        template <typename OtherRatio>
        static constexpr DigitalSize explicit_cast_from(
            const DigitalSize<OtherRatio>& other
        ) noexcept;

        // ---- Arithmetic ----

        /**
         * @brief Adds another DigitalSize of any unit to this one.
         *
         * Both operands are canonicalized to the finer of the two units before
         * addition. The result type is the finer of the two input types.
         */
        template <typename OtherRatio>
        constexpr auto operator+(const DigitalSize<OtherRatio>& other) const noexcept;

        /**
         * @brief Subtracts another DigitalSize of any unit from this one.
         *
         * Both operands are canonicalized to the finer of the two units before
         * subtraction. The result type is the finer of the two input types.
         *
         * @throws std::underflow_error if the subtraction would produce a
         *         negative result. DigitalSize is an unsigned quantity; callers
         *         who want the symmetric gap between two values should use
         *         absoluteDifference() instead.
         */
        template <typename OtherRatio>
        auto operator-(const DigitalSize<OtherRatio>& other) const;

        /**
         * @brief Multiplies this DigitalSize by a scalar.
         *
         * Unit is preserved; only the count is scaled.
         */
        constexpr DigitalSize operator*(rep_type scalar) const noexcept;

        /**
         * @brief Divides this DigitalSize by a scalar.
         *
         * Unit is preserved; only the count is scaled. Integer division rules apply.
         *
         * @throws std::invalid_argument if scalar is zero.
         */
        DigitalSize operator/(rep_type scalar) const;

        /**
         * @brief Divides this DigitalSize by another DigitalSize, yielding a ratio.
         *
         * Both operands are canonicalized to bytes before division. The result
         * is a dimensionless scalar.
         *
         * @throws std::invalid_argument if the divisor is zero.
         */
        template <typename OtherRatio>
        rep_type operator/(const DigitalSize<OtherRatio>& other) const;

        // ---- Compound assignment ----

        template <typename OtherRatio>
        constexpr DigitalSize& operator+=(const DigitalSize<OtherRatio>& other) noexcept;

        template <typename OtherRatio>
        DigitalSize& operator-=(const DigitalSize<OtherRatio>& other);

        constexpr DigitalSize& operator*=(rep_type scalar) noexcept;

        DigitalSize& operator/=(rep_type scalar);

        // ---- Comparison ----

        /**
         * @brief Three-way comparison against another DigitalSize of any unit.
         *
         * Both operands are canonicalized to bytes before comparison, so
         * 1_MiB == 1024_KiB evaluates to true.
         */
        template <typename OtherRatio>
        constexpr std::strong_ordering operator<=>(
            const DigitalSize<OtherRatio>& other
        ) const noexcept;

        template <typename OtherRatio>
        constexpr bool operator==(
            const DigitalSize<OtherRatio>& other
        ) const noexcept;

        // ---- Symmetric operations ----

        /**
         * @brief Returns the absolute difference between this and another DigitalSize.
         *
         * Unlike operator-, this operation is direction-independent: it returns
         * the positive gap between the two values regardless of which is larger.
         * Result type is the finer of the two input types.
         *
         * Use this when the meaningful quantity is "how far apart are these two
         * sizes," rather than "what is a minus b."
         */
        template <typename OtherRatio>
        constexpr auto absoluteDifference(
            const DigitalSize<OtherRatio>& other
        ) const noexcept;

    private:
        rep_type m_count{0};
    };

    // ---- Free-function scalar multiplication (commutative) ----

    template <typename Ratio>
    constexpr DigitalSize<Ratio> operator*(
        typename DigitalSize<Ratio>::rep_type scalar,
        const DigitalSize<Ratio>& size
    ) noexcept;

} // namespace chevron::common::units
```

