```cpp
#include "chevron/common/units/DigitalSize.hpp"

#include <cstddef>
#include <cstdint>
#include <compare>
#include <limits>
#include <ratio>
#include <stdexcept>
#include <type_traits>

namespace chevron::common::units {

    // ========================================================================
    // Internal ratio math helpers
    // ========================================================================
    //
    // These helpers encode the ratio arithmetic that underpins both implicit
    // conversion and heterogeneous arithmetic. They are the single source of
    // truth for "how do two DigitalSize types relate to each other."
    //

    namespace detail {

        /**
         * @brief True if ratio From is losslessly convertible to ratio To.
         *
         * A conversion is lossless when every integer count in From maps to
         * an integer count in To without truncation. This is true precisely
         * when From::num * To::den is an integer multiple of To::num * From::den —
         * equivalently, when the reduced ratio From/To has denominator 1.
         */
        template <typename From, typename To>
        constexpr bool is_lossless_conversion_v =
            std::ratio_divide<From, To>::den == 1;

        /**
         * @brief The finer (smaller-unit) of two ratios.
         *
         * Used to determine the common type for heterogeneous arithmetic.
         * The finer ratio is the one that represents fewer bytes per unit.
         */
        template <typename A, typename B>
        using finer_ratio_t = std::conditional_t<
            std::ratio_less_v<A, B>, A, B
        >;

        /**
         * @brief Converts a count from one ratio to another without overflow checking.
         *
         * count_in_to = count_in_from * (From::num * To::den) / (To::num * From::den)
         *
         * For lossless conversions the division is exact. For lossy conversions
         * the result truncates toward zero (standard integer division behavior).
         */
        template <typename From, typename To>
        constexpr std::uint64_t convert_count(std::uint64_t count) noexcept {
            using Factor = std::ratio_divide<From, To>;
            return (count * Factor::num) / Factor::den;
        }

    } // namespace detail

    // ========================================================================
    // Construction
    // ========================================================================

    template <typename Ratio>
    constexpr DigitalSize<Ratio>::DigitalSize(rep_type count) noexcept
        : m_count{count}
    {}

    template <typename Ratio>
    template <typename OtherRatio>
    constexpr DigitalSize<Ratio>::DigitalSize(
        const DigitalSize<OtherRatio>& other
    ) noexcept
        requires (detail::is_lossless_conversion_v<OtherRatio, Ratio>)
        : m_count{detail::convert_count<OtherRatio, Ratio>(other.count())}
    {}

    // ========================================================================
    // Accessors
    // ========================================================================

    template <typename Ratio>
    constexpr typename DigitalSize<Ratio>::rep_type
    DigitalSize<Ratio>::count() const noexcept {
        return m_count;
    }

    template <typename Ratio>
    constexpr typename DigitalSize<Ratio>::rep_type
    DigitalSize<Ratio>::bytes() const noexcept {
        // Multiply the stored count by this unit's byte-size.
        // For Bytes (Ratio == ratio<1,1>) this is a no-op the compiler elides.
        return m_count * Ratio::num / Ratio::den;
    }

    template <typename Ratio>
    std::size_t DigitalSize<Ratio>::to_size_t() const {
        const rep_type byte_count = bytes();

        // On 64-bit platforms, size_t is 64-bit and this check is dead code
        // the compiler will eliminate. On 32-bit platforms it's a real guard.
        if constexpr (sizeof(std::size_t) < sizeof(rep_type)) {
            if (byte_count > std::numeric_limits<std::size_t>::max()) {
                throw std::overflow_error{
                    "DigitalSize::to_size_t: byte count exceeds size_t capacity"
                };
            }
        }

        return static_cast<std::size_t>(byte_count);
    }

    // ========================================================================
    // Explicit conversion
    // ========================================================================

    template <typename Ratio>
    template <typename OtherRatio>
    constexpr DigitalSize<Ratio> DigitalSize<Ratio>::explicit_cast_from(
        const DigitalSize<OtherRatio>& other
    ) noexcept {
        // Unconditional conversion — truncation is accepted as the contract here.
        return DigitalSize<Ratio>{
            detail::convert_count<OtherRatio, Ratio>(other.count())
        };
    }

    // ========================================================================
    // Arithmetic
    // ========================================================================

    template <typename Ratio>
    template <typename OtherRatio>
    constexpr auto DigitalSize<Ratio>::operator+(
        const DigitalSize<OtherRatio>& other
    ) const noexcept {
        // Promote both operands to the finer of the two ratios, then add.
        using CommonRatio = detail::finer_ratio_t<Ratio, OtherRatio>;
        using Result = DigitalSize<CommonRatio>;

        const auto lhs = detail::convert_count<Ratio, CommonRatio>(m_count);
        const auto rhs = detail::convert_count<OtherRatio, CommonRatio>(other.count());

        return Result{lhs + rhs};
    }

    template <typename Ratio>
    template <typename OtherRatio>
    auto DigitalSize<Ratio>::operator-(
        const DigitalSize<OtherRatio>& other
    ) const {
        using CommonRatio = detail::finer_ratio_t<Ratio, OtherRatio>;
        using Result = DigitalSize<CommonRatio>;

        const auto lhs = detail::convert_count<Ratio, CommonRatio>(m_count);
        const auto rhs = detail::convert_count<OtherRatio, CommonRatio>(other.count());

        if (rhs > lhs) {
            throw std::underflow_error{
                "DigitalSize::operator-: subtraction would produce a negative result; "
                "use absoluteDifference() for the symmetric gap"
            };
        }

        return Result{lhs - rhs};
    }

    template <typename Ratio>
    constexpr DigitalSize<Ratio> DigitalSize<Ratio>::operator*(
        rep_type scalar
    ) const noexcept {
        return DigitalSize<Ratio>{m_count * scalar};
    }

    template <typename Ratio>
    DigitalSize<Ratio> DigitalSize<Ratio>::operator/(rep_type scalar) const {
        if (scalar == 0) {
            throw std::invalid_argument{
                "DigitalSize::operator/: division by zero"
            };
        }
        return DigitalSize<Ratio>{m_count / scalar};
    }

    template <typename Ratio>
    template <typename OtherRatio>
    typename DigitalSize<Ratio>::rep_type DigitalSize<Ratio>::operator/(
        const DigitalSize<OtherRatio>& other
    ) const {
        // Both sides canonicalized to bytes for a dimensionally honest division.
        const rep_type rhs = other.bytes();

        if (rhs == 0) {
            throw std::invalid_argument{
                "DigitalSize::operator/: division by zero-sized quantity"
            };
        }

        return bytes() / rhs;
    }

    // ========================================================================
    // Compound assignment
    // ========================================================================

    template <typename Ratio>
    template <typename OtherRatio>
    constexpr DigitalSize<Ratio>& DigitalSize<Ratio>::operator+=(
        const DigitalSize<OtherRatio>& other
    ) noexcept {
        // Convert the rhs into this type's unit and accumulate.
        // Note: this only compiles when OtherRatio is losslessly convertible
        // to Ratio — otherwise the compound form would silently truncate.
        static_assert(
            detail::is_lossless_conversion_v<OtherRatio, Ratio>,
            "operator+= requires the right-hand side's unit to be losslessly "
            "convertible to the left-hand side's unit. Use operator+ for "
            "heterogeneous addition that promotes to a common finer unit."
        );

        m_count += detail::convert_count<OtherRatio, Ratio>(other.count());
        return *this;
    }

    template <typename Ratio>
    template <typename OtherRatio>
    DigitalSize<Ratio>& DigitalSize<Ratio>::operator-=(
        const DigitalSize<OtherRatio>& other
    ) {
        static_assert(
            detail::is_lossless_conversion_v<OtherRatio, Ratio>,
            "operator-= requires the right-hand side's unit to be losslessly "
            "convertible to the left-hand side's unit. Use operator- for "
            "heterogeneous subtraction that promotes to a common finer unit."
        );

        const rep_type rhs = detail::convert_count<OtherRatio, Ratio>(other.count());

        if (rhs > m_count) {
            throw std::underflow_error{
                "DigitalSize::operator-=: subtraction would produce a negative result"
            };
        }

        m_count -= rhs;
        return *this;
    }

    template <typename Ratio>
    constexpr DigitalSize<Ratio>& DigitalSize<Ratio>::operator*=(
        rep_type scalar
    ) noexcept {
        m_count *= scalar;
        return *this;
    }

    template <typename Ratio>
    DigitalSize<Ratio>& DigitalSize<Ratio>::operator/=(rep_type scalar) {
        if (scalar == 0) {
            throw std::invalid_argument{
                "DigitalSize::operator/=: division by zero"
            };
        }
        m_count /= scalar;
        return *this;
    }

    // ========================================================================
    // Comparison
    // ========================================================================

    template <typename Ratio>
    template <typename OtherRatio>
    constexpr std::strong_ordering DigitalSize<Ratio>::operator<=>(
        const DigitalSize<OtherRatio>& other
    ) const noexcept {
        // Canonicalize both sides to bytes and compare.
        // This makes 1_MiB <=> 1024_KiB yield strong_ordering::equal.
        return bytes() <=> other.bytes();
    }

    template <typename Ratio>
    template <typename OtherRatio>
    constexpr bool DigitalSize<Ratio>::operator==(
        const DigitalSize<OtherRatio>& other
    ) const noexcept {
        return bytes() == other.bytes();
    }

    // ========================================================================
    // Symmetric operations
    // ========================================================================

    template <typename Ratio>
    template <typename OtherRatio>
    constexpr auto DigitalSize<Ratio>::absoluteDifference(
        const DigitalSize<OtherRatio>& other
    ) const noexcept {
        using CommonRatio = detail::finer_ratio_t<Ratio, OtherRatio>;
        using Result = DigitalSize<CommonRatio>;

        const auto lhs = detail::convert_count<Ratio, CommonRatio>(m_count);
        const auto rhs = detail::convert_count<OtherRatio, CommonRatio>(other.count());

        // Symmetric: always subtract smaller from larger.
        return (lhs >= rhs) ? Result{lhs - rhs} : Result{rhs - lhs};
    }

    // ========================================================================
    // Free-function scalar multiplication (commutative)
    // ========================================================================

    template <typename Ratio>
    constexpr DigitalSize<Ratio> operator*(
        typename DigitalSize<Ratio>::rep_type scalar,
        const DigitalSize<Ratio>& size
    ) noexcept {
        return size * scalar;
    }

} // namespace chevron::common::units
