#include "chevron/utility/bits/alignment.hpp"

#include <cstddef>
#include <cstdint>
#include <stdexcept>

namespace chevron::bits {

    std::size_t align_up(std::size_t value, std::size_t alignment) {
        if (alignment == 0) {
            throw std::invalid_argument{
                "align_up: alignment must be non-zero"
            };
        }

        // Round up by adding (alignment - 1), then truncating the remainder.
        // For value already aligned, the remainder is zero and value is unchanged.
        const std::size_t remainder = value % alignment;
        if (remainder == 0) {
            return value;
        }
        return value + (alignment - remainder);
    }

    template <typename T>
    T* align_up(T* ptr, std::size_t alignment) {
        const auto address = reinterpret_cast<std::uintptr_t>(ptr);
        const auto aligned = static_cast<std::uintptr_t>(
            align_up(static_cast<std::size_t>(address), alignment)
        );
        return reinterpret_cast<T*>(aligned);
    }

    std::size_t align_down(std::size_t value, std::size_t alignment) {
        if (alignment == 0) {
            throw std::invalid_argument{
                "align_down: alignment must be non-zero"
            };
        }

        // Round down by truncating the remainder.
        return value - (value % alignment);
    }

    template <typename T>
    T* align_down(T* ptr, std::size_t alignment) {
        const auto address = reinterpret_cast<std::uintptr_t>(ptr);
        const auto aligned = static_cast<std::uintptr_t>(
            align_down(static_cast<std::size_t>(address), alignment)
        );
        return reinterpret_cast<T*>(aligned);
    }

} // namespace chevron::bits
