#include "chevron/units/DigitalSize.hpp"

#include <cstddef>
#include <cstdint>
#include <compare>
#include <limits>
#include <ratio>
#include <stdexcept>
#include <type_traits>

namespace chevron::units {

    // ========================================================================
    // DigitalSizeCast
    // ========================================================================

    template <typename To_Units>
    template <typename From_Units>
    constexpr To_Units DigitalSizeCast<To_Units>::cast(
        const From_Units& source
    ) noexcept {
        using SourceRatio = typename From_Units::ByteRatio;
        using TargetRatio = typename To_Units::ByteRatio;
        using Factor = std::ratio_divide<SourceRatio, TargetRatio>;

        return To_Units{
            (source.count() * Factor::num) / Factor::den
        };
    }

    template <typename To_Units, typename From_Units>
    constexpr To_Units size_cast(const From_Units& source) noexcept {
        return DigitalSizeCast<To_Units>::cast(source);
    }

    // ========================================================================
    // Construction
    // ========================================================================

    template <std::uint64_t Bytes_Per_Unit>
    constexpr DigitalSize<Bytes_Per_Unit>::DigitalSize(rep_type count) noexcept
        : m_count{count}
    {}

    template <std::uint64_t Bytes_Per_Unit>
    template <std::uint64_t Other_Bytes_Per_Unit>
    constexpr DigitalSize<Bytes_Per_Unit>::DigitalSize(
        const DigitalSize<Other_Bytes_Per_Unit>& other
    ) noexcept
        requires (traits::is_lossless_size_conversion_v<
            DigitalSize<Other_Bytes_Per_Unit>,
            DigitalSize<Bytes_Per_Unit>
        >)
        : m_count{size_cast<DigitalSize>(other).count()}
    {}

    // ========================================================================
    // Accessors
    // ========================================================================

    template <std::uint64_t Bytes_Per_Unit>
    constexpr typename DigitalSize<Bytes_Per_Unit>::rep_type
    DigitalSize<Bytes_Per_Unit>::count() const noexcept {
        return m_count;
    }

    template <std::uint64_t Bytes_Per_Unit>
    constexpr typename DigitalSize<Bytes_Per_Unit>::rep_type
    DigitalSize<Bytes_Per_Unit>::bytes() const noexcept {
        // For Bytes (Bytes_Per_Unit == 1) this is a no-op the compiler elides.
        return m_count * Bytes_Per_Unit;
    }

    template <std::uint64_t Bytes_Per_Unit>
    std::size_t DigitalSize<Bytes_Per_Unit>::to_size_t() const {
        const rep_type byte_count = bytes();

        if constexpr (sizeof(std::size_t) < sizeof(rep_type)) {
            if (byte_count > std::numeric_limits<std::size_t>::max()) {
                throw std::overflow_error{
                    "DigitalSize::to_size_t: byte count exceeds size_t capacity"
                };
            }
        }

        return static_cast<std::size_t>(byte_count);
    }

    // ========================================================================
    // Arithmetic
    // ========================================================================

    template <std::uint64_t Bytes_Per_Unit>
    template <std::uint64_t Other_Bytes_Per_Unit>
    constexpr auto DigitalSize<Bytes_Per_Unit>::operator+(
        const DigitalSize<Other_Bytes_Per_Unit>& other
    ) const noexcept {
        using Common = traits::finer_unit_t<
            DigitalSize<Bytes_Per_Unit>,
            DigitalSize<Other_Bytes_Per_Unit>
        >;

        const Common lhs = size_cast<Common>(*this);
        const Common rhs = size_cast<Common>(other);

        return Common{lhs.count() + rhs.count()};
    }

