```cpp
#include "chevron/utility/bits/power_of_two.hpp"

#include <bit>
#include <concepts>
#include <limits>
#include <stdexcept>

namespace chevron::bits {

    template <std::unsigned_integral T>
    constexpr bool is_power_of_two(T value) noexcept {
        return std::has_single_bit(value);
    }

    template <std::unsigned_integral T>
    constexpr T next_power_of_two(T value) {
        // The largest representable power of two for T is 1 << (bit width - 1).
        // For uint64_t that's 1 << 63 == 2^63. Any value larger than that has
        // no power-of-two ceiling within T's range.
        constexpr T max_power_of_two =
            T{1} << (std::numeric_limits<T>::digits - 1);

        if (value > max_power_of_two) {
            throw std::overflow_error{
                "next_power_of_two: value exceeds the maximum representable "
                "power of two for the target type"
            };
        }

        // std::bit_ceil returns 1 for input 0, which matches our contract.
        return std::bit_ceil(value);
    }

    template <std::unsigned_integral T>
    constexpr T previous_power_of_two(T value) {
        if (value == 0) {
            throw std::invalid_argument{
                "previous_power_of_two: zero has no previous power of two"
            };
        }

        return std::bit_floor(value);
    }

} // namespace chevron::bits
