namespace chevron::units::traits {

    // ---- std::ratio detection helper ----

    namespace detail {

        /*! @brief Primary template: by default, T is not a std::ratio specialization. */
        template <typename T>
        struct is_std_ratio : std::false_type {};

        /*! @brief Partial specialization: any std::ratio<Num, Den> matches. */
        template <std::intmax_t Num, std::intmax_t Den>
        struct is_std_ratio<std::ratio<Num, Den>> : std::true_type {};

        /*! @brief Variable-template form for convenient use. */
        template <typename T>
        constexpr bool is_std_ratio_v = is_std_ratio<T>::value;

    } // namespace detail

    // ---- Shape predicate ----

    /*! @brief True if T has a nested ByteRatio typedef that is a std::ratio specialization. */
    template <typename T>
    constexpr bool has_byte_ratio_spec_v = requires {
        typename T::ByteRatio;
        requires detail::is_std_ratio_v<typename T::ByteRatio>;
    };

    // ---- Size system classification ----

    /*! @brief True if T's byte-per-unit is a power of two — i.e., T belongs to the IEC binary size system. */
    template <typename T>
    constexpr bool is_binary_size_system_v =
        has_byte_ratio_spec_v<T>
        && (T::ByteRatio::den == 1)
        && chevron::bits::is_power_of_two(static_cast<std::uint64_t>(T::ByteRatio::num));

    /*! @brief True if T's byte-per-unit is a power of ten — i.e., T belongs to the SI decimal size system. */
    template <typename T>
    constexpr bool is_decimal_size_system_v =
        has_byte_ratio_spec_v<T>
        && (T::ByteRatio::den == 1)
        && chevron::bits::is_power_of_ten(static_cast<std::uint64_t>(T::ByteRatio::num));

    /*! @brief True if A and B both belong to the same size system (both binary or both decimal). */
    template <typename A, typename B>
    constexpr bool is_same_size_system_v =
        (is_binary_size_system_v<A> && is_binary_size_system_v<B>)
        || (is_decimal_size_system_v<A> && is_decimal_size_system_v<B>);

} // namespace chevron::units::traits
