/*!
 * @brief
 * Adds another digital size of any unit to this one in place.
 *
 * @details
 * The right-hand side is cast to this type's unit before being added.
 * Casts that lose information truncate toward zero — adding a finer
 * unit to a coarser one may have no effect if the finer value falls
 * below this type's resolution.
 *
 * @return Reference to this DigitalSize after the addition.
 */
template <uint64_t IncomingUnitBytes>
