{
    using Self = DigitalSize<UnitBytes>;

    this->unitCount_ += DigitalSizeCast<Self>::cast(other).count();
    return *this;
}

/*!
 * @brief
 * Subtracts another digital size of any unit from this one in place.
 *
 * @details
 * The right-hand side is cast to this type's unit before being subtracted.
 * Casts that lose information truncate toward zero — subtracting a finer
 * unit from a coarser one may have no effect if the finer value falls
 * below this type's resolution.
 *
 * @return Reference to this DigitalSize after the subtraction.
 */
template <uint64_t IncomingUnitBytes>
DigitalSize<UnitBytes>& operator-=(const DigitalSize<IncomingUnitBytes>& other) noexcept
{
    using Self = DigitalSize<UnitBytes>;

    this->unitCount_ -= DigitalSizeCast<Self>::cast(other).count();
    return *this;
}

/*!
 * @brief
 * Multiplies this DigitalSize by a scalar in place.
 *
 * @details
 * The unit type is preserved; only the count is scaled.
 *
 * @return Reference to this DigitalSize after the multiplication.
 */
DigitalSize<UnitBytes>& operator*=(const ReprType scalar) noexcept
{
    this->unitCount_ *= scalar;
    return *this;
}

/*!
 * @brief
 * Divides this DigitalSize by a scalar in place.
 *
 * @details
 * The unit type is preserved; only the count is scaled. Integer division
 * rules apply — fractional results are truncated toward zero.
 *
 * @return Reference to this DigitalSize after the division.
 *
 * @throws std::invalid_argument if `scalar` is zero.
 */
DigitalSize<UnitBytes>& operator/=(const ReprType scalar)
{
    if (scalar == 0) {
        throw std::invalid_argument{ "DigitalSize::operator/=(): Division by zero." };
    }

    this->unitCount_ /= scalar;
    return *this;
}
